def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping intervals in both a and b
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    result = []

    # For each interval in a, subtract all intervals in b
    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the non-overlapping parts
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if curr_end > b_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge touching intervals
    if not result:
        return []

    result = sorted(result)
    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

